-- Import the real menu Bill of Materials from COGS.xlsx (Hardi Coffee And Eatery,
-- generated 09-11-2026) into recipes for every outlet. Approved 2026-11-17:
--  * wipes the test stock: all stock items, balances, movements, recipes, the stock
--    purchase journals and the ORDER_COGS journals (so Persediaan = 0 = stock);
--    test orders and their sale journals stay, with hpp_total reset to 0
--  * lines marked "GAK USAH / JANGAN MASUK BOM" and Oreo (Cookies n Cream) are skipped
--  * "Milky Mango / Berry" and "Mango Blast / Berry Blast" are split; the Berry variants
--    become new products with the same prices
--  * sheets with no product in the catalogue are skipped: Mie Nyemek, MOUNT BLANC, CHOCO STRIP
-- Generated by a one-off script; edit recipes in the app afterwards, not here.
SET autocommit = 0;
START TRANSACTION;

-- 1. Clear test stock + its journals.
CREATE TEMPORARY TABLE tmp_stock_journals (id BIGINT UNSIGNED PRIMARY KEY);
INSERT IGNORE INTO tmp_stock_journals SELECT id FROM journal_entries WHERE source_type = 'ORDER_COGS';
INSERT IGNORE INTO tmp_stock_journals SELECT DISTINCT journal_entry_id FROM journal_lines WHERE stock_item_id IS NOT NULL;
DELETE jl FROM journal_lines jl JOIN tmp_stock_journals t ON t.id = jl.journal_entry_id;
DELETE je FROM journal_entries je JOIN tmp_stock_journals t ON t.id = je.id;
DROP TEMPORARY TABLE tmp_stock_journals;
UPDATE order_items SET hpp_total = 0;
DELETE FROM inventory_movements;
DELETE FROM inventory_stocks;
UPDATE outlet_products SET recipe_id = NULL;
DELETE FROM recipe_items;
DELETE FROM recipes;
DELETE FROM stock_items;

-- 2. Units.
INSERT INTO units (code, name, unit_group, base_conversion)
SELECT 'PORSI', 'Porsi', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM units WHERE code = 'PORSI');

-- 3. Split combined products.
UPDATE products SET name = 'Milky Mango' WHERE sku = 'BEV-00016';
UPDATE products SET name = 'Mango Blast' WHERE sku = 'BEV-00023';
INSERT INTO products (sku, name, description, image_url, category_id, product_type, base_unit_id, status)
SELECT 'BEV-00039', 'Milky Berry', NULL, NULL, category_id, product_type, base_unit_id, status FROM products WHERE sku = 'BEV-00016';
INSERT INTO outlet_products (outlet_id, product_id, channel, selling_price, tax_rate, is_available)
SELECT op.outlet_id, (SELECT id FROM products WHERE sku = 'BEV-00039'), op.channel, op.selling_price, op.tax_rate, op.is_available
FROM outlet_products op JOIN products p ON p.id = op.product_id WHERE p.sku = 'BEV-00016';
INSERT INTO products (sku, name, description, image_url, category_id, product_type, base_unit_id, status)
SELECT 'BEV-00040', 'Berry Blast', NULL, NULL, category_id, product_type, base_unit_id, status FROM products WHERE sku = 'BEV-00023';
INSERT INTO outlet_products (outlet_id, product_id, channel, selling_price, tax_rate, is_available)
SELECT op.outlet_id, (SELECT id FROM products WHERE sku = 'BEV-00040'), op.channel, op.selling_price, op.tax_rate, op.is_available
FROM outlet_products op JOIN products p ON p.id = op.product_id WHERE p.sku = 'BEV-00023';

